USE ops_ticket;
CREATE TABLE IF NOT EXISTS event_outbox (id BIGINT NOT NULL AUTO_INCREMENT,event_id CHAR(36) NOT NULL,aggregate_type VARCHAR(64) NOT NULL,aggregate_id BIGINT NOT NULL,event_type VARCHAR(128) NOT NULL,payload JSON NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'PENDING',retry_count INT NOT NULL DEFAULT 0,next_retry_time DATETIME,create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY uk_outbox_event(event_id),KEY idx_outbox_publish(status,next_retry_time,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mq_consumed_event (id BIGINT NOT NULL AUTO_INCREMENT,consumer_name VARCHAR(128) NOT NULL,event_id CHAR(36) NOT NULL,consume_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY uk_consumer_event(consumer_name,event_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
